{
  "appName": "Online Learning Platform",
  "appType": "e-learning",
  "summary": "An online learning platform where instructors publish courses and students enroll, complete lessons, and provide reviews, with a freemium model offering access to paid courses and certificates via subscription.",
  "entities": [
    {
      "name": "course",
      "fields": ["title", "description", "instructorId", "price", "isFree"]
    },
    {
      "name": "lesson",
      "fields": ["title", "videoUrl", "courseId"]
    },
    {
      "name": "enrollment",
      "fields": ["userId", "courseId", "enrollmentDate"]
    },
    {
      "name": "lessonCompletion",
      "fields": ["userId", "lessonId", "completionDate"]
    },
    {
      "name": "review",
      "fields": ["userId", "courseId", "rating", "comment"]
    },
    {
      "name": "subscription",
      "fields": ["userId", "startDate", "endDate", "planType"]
    }
  ],
  "roles": ["instructor", "student", "admin"],
  "features": ["auth", "courseManagement", "lessonManagement", "enrollment", "progressTracking", "reviews", "dashboard", "payments", "subscriptions", "certificates"],
  "hasAuth": true,
  "hasPayments": true,
  "ambiguities": [],
  "assumptions": [
    "There will be an admin role to manage the platform.",
    "Users will have profiles to store their information.",
    "Completion certificates are generated automatically upon course completion for subscribed users."
  ],
  "clarifyingQuestions": []
}
